-- Généré par tests/build_guide.lua depuis GUIDE.frFR.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.frFR = {
    { "h1", "Guide de Panorama" },
    { "p", "Comment utiliser Panorama sur WoW Forever, et comment configurer le HDR sous Windows." },
    { "p", "|cffffd100Sauvegardez d'abord vos réglages.|r Panorama modifie des réglages du jeu, et retirer l'addon ne les remet pas comme avant. Avant de changer quoi que ce soit, quittez le jeu et copiez le dossier |cffffd100WTF|r de votre installation du jeu en lieu sûr. Pour revenir en arrière, quittez le jeu et remettez cette copie à sa place." },
    { "h2", "1. Ouvrir la fenêtre" },
    { "li", "Tapez |cffffd100/pano|r, ou faites un clic gauche sur le bouton Panorama de la minimap.", "-" },
    { "li", "Options > AddOns > Panorama a aussi un bouton qui l'ouvre.", "-" },
    { "li", "Faites glisser la barre de titre pour déplacer la fenêtre. Échap ou le bouton de fermeture la ferme.", "-" },
    { "p", "Le bouton de la minimap :" },
    { "li", "Le clic gauche ouvre ou ferme la fenêtre.", "-" },
    { "li", "Le clic droit affiche les préréglages, l'annulation, le rétablissement et le redémarrage graphique.", "-" },
    { "li", "Faites-le glisser pour le déplacer autour de la minimap. |cffffd100/pano minimap|r l'affiche ou le masque.", "-" },
    { "h2", "2. La fenêtre" },
    { "row", "Champ de recherche (en haut à droite)", "Tapez un mot pour lister les réglages correspondants de tous les onglets. Videz-le pour revenir." },
    { "row", "Onglets", "Qualité, Interface, Avancé (réglages du jeu), puis Filtres, Mes filtres, Ambiance (effets de Panorama). L'onglet ouvert est mémorisé." },
    { "row", "Réglages avancés (sous le titre)", "Décoché : pas d'onglets, une seule page avec les préréglages, les réglages principaux de qualité (distance d'affichage, brouillard volumétrique, ombres, occlusion ambiante, détail de l'eau, anticrénelage, atténuation de la netteté), la sortie HDR et la crête, le contraste, la luminosité, le recul de la caméra, le filtre, l'intensité du filtre et le mode d'ambiance. Coché : tous les onglets et tous les réglages. À la première installation, il est décoché ; si vous utilisiez déjà Panorama, il est coché. La recherche trouve toujours tous les réglages." },
    { "row", "Annuler, Rétablir (sous les onglets, à droite)", "Annuler défait votre dernière modification : curseur, champ, préréglage, filtre, ambiance ou Tout réinitialiser. Rétablir la remet. Les 20 dernières modifications sont conservées jusqu'à |cffffd100/reload|r." },
    { "row", "Sélecteur de langue (à droite des onglets)", "Langue du jeu ou l'une des dix langues. Changer de langue recharge l'interface." },
    { "row", "Guide (à gauche du champ de recherche)", "Ouvre ce guide dans le jeu." },
    { "row", "Préréglages (onglet Qualité)", "Bas, Moyen, Élevé, Extra. Le préréglage qui correspond à vos réglages est mis en évidence." },
    { "row", "Pied de fenêtre", "Appliquer à chaque connexion, bouton minimap, Tout réinitialiser, redémarrage du moteur graphique." },
    { "p", "Cliquez sur un titre de section pour la replier ou la déplier." },
    { "h3", "Une ligne de réglage" },
    { "li", "|cffffd100Curseur|r : la valeur est écrite quand vous relâchez le bouton de la souris, pas pendant que vous faites glisser.", "-" },
    { "li", "|cffffd100Champ de valeur|r à côté du curseur : tapez une valeur, puis appuyez sur Entrée ou cliquez ailleurs. Échap annule, Tab passe au champ suivant. La virgule fonctionne comme séparateur décimal. La valeur reste dans la plage du curseur.", "-" },
    { "li", "|cffffd100Bouton Défaut|r : remet ce réglage à sa valeur par défaut. Survolez-le pour voir la valeur.", "-" },
    { "li", "|cffffd100Marque dorée|r à gauche : vous avez modifié ce réglage.", "-" },
    { "li", "|cffffd100Étoile jaune|r : un menu du jeu définit aussi cette valeur. Survolez-la pour voir lequel. Ce menu ne relit pas la valeur, il peut donc afficher un autre niveau.", "-" },
    { "li", "|cffffd100Ligne grisée|r : elle dépend d'un autre réglage désactivé (par exemple la densité du brouillard sans brouillard volumétrique, l'intensité de la teinte sans teinte). La ligne dit quel réglage changer.", "-" },
    { "li", "Survolez un libellé pour lire son aide complète.", "-" },
    { "h2", "3. Préréglages" },
    { "row", "Bas", "Performances maximales. Vue courte, sans ombres." },
    { "row", "Moyen", "Équilibré. Bonnes performances, ombres correctes." },
    { "row", "Élevé", "Niveau Élevé du jeu. Ombres complètes, tous les effets." },
    { "row", "Extra", "Qualité maximale. Vue la plus lointaine, tout activé." },
    { "p", "Les préréglages ne modifient que les réglages de qualité graphique de l'onglet Qualité. Ils ne touchent pas à la caméra, à la souris, à l'interface, à la netteté, à la faible latence, au HDR ni aux filtres." },
    { "p", "Vous avez changé d'avis ? |cffffd100Annuler|r (sous les onglets, ou |cffffd100/pano undo|r) rétablit les réglages d'avant le préréglage." },
    { "h2", "4. Filtres" },
    { "p", "L'onglet Filtres ajoute des effets par-dessus l'image. Ils ne changent aucun réglage du jeu." },
    { "li", "|cffffd100Teinte|r : cliquez sur une vignette pour l'appliquer tout de suite (sépia, chaude, froide, nuit, émeraude, crépuscule). |cffffd100Intensité de la teinte|r règle sa force.", "-" },
    { "li", "|cffffd100Mon filtre|r : utilise un de vos filtres de l'onglet Mes filtres. Il remplace la teinte, la vignette et le grain.", "-" },
    { "li", "|cffffd100Ciel|r : les mêmes couleurs en dégradé, pleines en haut de l'écran et plus claires en bas. |cffffd100Intensité du ciel|r règle sa force.", "-" },
    { "li", "|cffffd100Vignettage|r : assombrit les bords de l'écran.", "-" },
    { "li", "|cffffd100Grain|r : grain animé.", "-" },
    { "li", "|cffffd100Bandes noires|r : bandes en haut et en bas, de 0 à 20 % de l'écran chacune. Le jeu calcule quand même ce qu'elles cachent, elles n'augmentent donc pas le nombre d'images par seconde.", "-" },
    { "h3", "Ambiance" },
    { "p", "L'onglet Ambiance change tout seul la teinte, le ciel, la vignette et le grain selon l'endroit où vous êtes." },
    { "li", "|cffffd100Mode|r (haut de l'onglet) : |cffffd100Désactivé|r (l'onglet Filtres s'applique partout), |cffffd100Jour et nuit automatiques|r (voir Jour et nuit plus bas) ou |cffffd100Ambiance auto|r. Désactivé par défaut.", "-" },
    { "li", "|cffffd100Ambiance auto|r : ces filtres suivent le lieu et l'heure. Les valeurs de l'onglet Filtres restent enregistrées et reviennent quand vous changez de mode. Sans Réglages avancés, la page unique n'affiche que le mode et le lieu détecté ; cochez Réglages avancés pour modifier les contextes.", "-" },
    { "li", "|cffffd100Lieu|r : règle la teinte, la vignette et le grain. Ordre : donjon ou raid, intérieur, météo (pluie, neige, tempête de sable), puis le type de zone : terres tempérées, déserts et terres arides, terres enneigées, jungle et marais, terres corrompues, terres volcaniques, forêts arcaniques. Une zone pas encore connue compte comme tempérée. La météo ne compte que si Intensité météo est supérieure à 0.", "-" },
    { "li", "|cffffd100Heure|r : règle le ciel (jour, aube et crépuscule, nuit). La nuit suit le jour et la nuit du jeu ; l'aube et le crépuscule suivent l'heure du serveur. Pas de ciel en intérieur ni en donjon.", "-" },
    { "li", "La ligne de droite montre le lieu et l'heure détectés maintenant. Quand un donjon, un intérieur ou la météo passe avant une zone que vous avez réglée, elle l'indique.", "-" },
    { "li", "|cffffd100Contexte à modifier|r : choisissez un contexte, puis réglez ses filtres en dessous. Le bouton Défaut rend la valeur livrée pour ce contexte. Le menu est rangé en cinq groupes : |cffffd100Zones|r (la zone où vous êtes et celles que vous avez réglées), |cffffd100Donjon et intérieur|r, |cffffd100Météo|r, |cffffd100Type de zone|r et |cffffd100Ciel (moment)|r. Les quatre premiers règlent la teinte, la vignette, le grain et un préréglage graphique : un seul lieu s'applique à la fois, dans l'ordre donné plus haut. Le dernier règle le ciel. Rien à régler pour commencer : chaque contexte a déjà ses valeurs.", "-" },
    { "li", "|cffffd100Cette zone|r : premier choix du même menu, avec le nom de la zone où vous êtes. Choisissez-la pour donner à cette zone sa propre teinte, sa propre vignette et son propre grain, en partant de son type de zone. Elle passe alors avant le type de zone, mais après donjon, intérieur et météo. Les zones que vous réglez restent dans le menu. |cffffd100Type de zone|r retire les valeurs de la zone : elle suit de nouveau son type de zone.", "-" },
    { "li", "|cffffd100Toutes les zones|r : sous-menu du même menu, avec toutes les zones connues. Choisissez-en une pour la régler sans y être. Les zones sont rangées par continent.", "-" },
    { "li", "|cffffd100Préréglage|r et |cffffd100Distance des décors|r (premières lignes d'un lieu ou d'une zone) : ils s'appliquent tant que vous êtes dans ce lieu, par-dessus vos propres réglages, que l'ambiance auto soit cochée ou non. La distance des décors du lieu passe avant celle du préréglage. Vos propres réglages sont conservés et reviennent quand vous partez. |cffffd100Mes réglages|r ne change rien. Exemple : Bas en donjon, Extra dans une zone que vous aimez. Dans un donjon ou un raid, le premier choix du menu règle ce donjon seul. Dans l'onglet Qualité, le bouton |cffffd100Par lieu|r ouvre ces lignes pour le lieu où vous êtes ; il affiche |cffffd100Ici : …|r tant qu'un lieu impose les siens. En combat, le changement attend la fin du combat.", "-" },
    { "li", "|cffffd100Mon filtre|r (première ligne des filtres d'un lieu ou d'une zone) : ce lieu utilise un de vos filtres de l'onglet Mes filtres, avec son contraste, sa luminosité et son gamma, tant que l'ambiance auto est cochée.", "-" },
    { "li", "|cffffd100Jour et nuit|r (mode |cffffd100Jour et nuit automatiques|r) : Panorama pose la |cffffd100Teinte de jour|r le jour et la |cffffd100Teinte de nuit|r la nuit, selon le jour et la nuit du jeu. Elles remplacent la teinte de l'onglet Filtres. Le passage est progressif de 19 h à 21 h et de 5 h à 7 h (heure du serveur). Les teintes de jour et de nuit et leurs intensités se règlent avec Réglages avancés.", "-" },
    { "h2", "5. Mes filtres" },
    { "p", "L'onglet Mes filtres (affiché avec Réglages avancés) sert à créer autant de filtres à vous que vous voulez. |cffffd100Nouveau|r en ajoute un, |cffffd100Supprimer|r retire le filtre ouvert : l'onglet Filtres, les lieux et les zones qui l'utilisaient repassent à Aucun." },
    { "li", "|cffffd100Filtre à modifier|r : choisit le filtre que règlent les lignes en dessous. |cffffd100Nom|r : donnez-lui un nom (Entrée pour valider).", "-" },
    { "li", "|cffffd100Rouge|r, |cffffd100Vert|r, |cffffd100Bleu|r (en %) : couleur de la teinte du filtre. |cffffd100Intensité de la teinte|r : sa force.", "-" },
    { "li", "|cffffd100Vignettage|r et |cffffd100Grain|r : ceux du filtre.", "-" },
    { "li", "|cffffd100Contraste|r, |cffffd100Luminosité|r, |cffffd100Gamma|r : réglages d'image que le filtre donne au jeu tant qu'il est appliqué ; vos propres valeurs reviennent ensuite. Mes réglages : rien ne change. Selon le mode d'affichage, ils peuvent rester sans effet.", "-" },
    { "li", "Tant que l'onglet est ouvert, le filtre affiché se voit en direct sur le jeu.", "-" },
    { "li", "Pour utiliser un filtre : choisissez-le à la ligne |cffffd100Mon filtre|r de l'onglet Filtres (partout), ou d'un lieu ou d'une zone dans l'onglet Ambiance (ambiance auto cochée). Il remplace alors la teinte, la vignette et le grain, dont les lignes sont grisées. Aucun : rien ne change.", "-" },
    { "h2", "6. Vos valeurs et le jeu" },
    { "li", "À la première installation, Panorama lit vos réglages actuels du jeu. Rien ne change tant que vous ne touchez pas un contrôle.", "-" },
    { "li", "Une modification faite dans le menu Graphismes du jeu ou avec |cffffd100/console|r apparaît dans la fenêtre.", "-" },
    { "li", "|cffffd100Appliquer à chaque connexion|r (pied de fenêtre, activé par défaut) : les réglages que vous avez modifiés dans Panorama sont réécrits à chaque connexion. Les autres suivent le menu Graphismes du jeu.", "-" },
    { "li", "Une modification faite en combat est appliquée à la fin du combat.", "-" },
    { "li", "Certains réglages, comme le MSAA, demandent un redémarrage graphique. Cliquez sur |cffffd100Redémarrer|r dans le pied de fenêtre, ou tapez |cffffd100/pano restart|r. L'écran clignote une seconde.", "-" },
    { "h2", "7. HDR sous Windows" },
    { "p", "Les réglages HDR n'existent que sous forme de commandes de console dans le jeu. Panorama les affiche dans l'onglet |cffffd100Avancé|r, section |cffffd100HDR (console seulement)|r. Il vous faut un écran compatible HDR." },
    { "h3", "Étape 1 : activer le HDR dans Windows" },
    { "p", "Windows 11 :" },
    { "li", "Ouvrez |cffffd100Paramètres > Système > Affichage|r.", "1." },
    { "li", "Sélectionnez l'écran HDR si vous en avez plusieurs.", "2." },
    { "li", "Activez |cffffd100Utiliser HDR|r. Le raccourci |cffffd100Win + Alt + B|r l'active ou le désactive aussi.", "3." },
    { "p", "Windows 10 : |cffffd100Paramètres > Système > Affichage > Paramètres de couleurs HD Windows|r (Windows HD Color settings), puis activez |cffffd100Lire des jeux et des applications HDR|r (Play HDR games and apps)." },
    { "p", "Vérifiez aussi que le HDR est activé dans le menu de l'écran lui-même, s'il a une telle option." },
    { "p", "Désactivez le |cffffd100HDR automatique|r (Auto HDR) de Windows 11 : |cffffd100Paramètres > Système > Affichage > HDR|r. Il sert aux jeux sans HDR. WoW produit sa propre image HDR." },
    { "h3", "Étape 2 : trouver la luminosité de crête de votre écran" },
    { "p", "Installez l'application gratuite |cffffd100Étalonnage HDR de Windows|r (Windows HDR Calibration) depuis le Microsoft Store et lancez-la. La luminance maximale qu'elle trouve est la luminosité de crête de votre écran, en nits." },
    { "p", "Sans l'application, utilisez la certification HDR de l'écran : DisplayHDR 400 signifie environ 400 nits, DisplayHDR 600 environ 600, DisplayHDR 1000 environ 1000." },
    { "h3", "Étape 3 : régler le HDR dans Panorama" },
    { "p", "Ouvrez |cffffd100/pano|r, onglet |cffffd100Avancé|r, section |cffffd100HDR (console seulement)|r." },
    { "li", "Cochez |cffffd100Sortie HDR|r.", "1." },
    { "li", "Cochez |cffffd100Luminosité de crête|r ou |cffffd100Luminosité de référence|r : l'un ou l'autre, jamais les deux. Sans l'un d'eux, l'image s'assombrit.", "2." },
    { "p", "|cffffd100Mode luminosité de crête (recommandé)|r" },
    { "li", "Cochez |cffffd100Luminosité de crête|r.", "-" },
    { "li", "Réglez |cffffd100Crête (nits)|r sur la valeur trouvée à l'étape 2.", "-" },
    { "li", "|cffffd100Intensité HDR|r ne fonctionne que dans ce mode. La valeur par défaut du jeu est 2. Changez-la par petits pas et comparez : Blizzard ne documente pas son effet exact.", "-" },
    { "p", "|cffffd100Mode luminosité de référence|r" },
    { "li", "Cochez |cffffd100Luminosité de référence|r.", "-" },
    { "li", "|cffffd100Référence (nits)|r est la luminosité du blanc dans la scène. 203 est la valeur standard. Augmentez-la si l'image paraît trop sombre dans une pièce lumineuse. Intensité HDR n'a aucun effet dans ce mode.", "-" },
    { "p", "Si l'image ne change pas, cliquez sur |cffffd100Redémarrer|r dans le pied de fenêtre." },
    { "h3", "Dépannage du HDR" },
    { "row", "Image très sombre", "Cochez l'un des deux modes de luminosité." },
    { "row", "Image grise ou délavée", "Activez le HDR dans Windows (étape 1) et dans le menu de l'écran." },
    { "row", "HDR automatique activé dans Windows", "Désactivez-le (étape 1)." },
    { "row", "Hautes lumières trop vives ou plates", "Réglez la luminosité de crête sur la valeur réelle de votre écran (étape 2)." },
    { "row", "Vous voulez désactiver le HDR", "Décochez |cffffd100Sortie HDR|r." },
    { "p", "Chaque ligne HDR a un bouton Défaut qui remet la valeur du jeu." },
    { "h2", "8. Commandes" },
    { "row", "|cffffd100/pano|r", "Ouvre ou ferme la fenêtre" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Applique un préréglage" },
    { "row", "|cffffd100/pano undo|r", "Annule la dernière modification" },
    { "row", "|cffffd100/pano redo|r", "Rétablit la modification que vous venez d'annuler" },
    { "row", "|cffffd100/pano reset|r", "Remet chaque réglage et chaque filtre par défaut" },
    { "row", "|cffffd100/pano status|r", "Affiche dans le chat le lieu et le moment détectés et les filtres appliqués à l'instant (pendant un fondu, les valeurs visées)" },
    { "row", "|cffffd100/pano apply|r", "Réécrit les réglages modifiés dans Panorama" },
    { "row", "|cffffd100/pano restart|r", "Redémarre le moteur graphique" },
    { "row", "|cffffd100/pano minimap|r", "Affiche ou masque le bouton de la minimap" },
    { "h2", "9. Réinitialisation" },
    { "li", "Le bouton |cffffd100Défaut|r de chaque ligne réinitialise ce réglage.", "-" },
    { "li", "Le bouton |cffffd100Par défaut|r du menu Graphismes du jeu réinitialise uniquement les réglages que ce menu gère, et Panorama le suit. Utilisez les boutons Défaut de |cffffd100/pano|r pour les autres et pour les filtres.", "-" },
    { "li", "|cffffd100Tout réinitialiser|r (pied de fenêtre, avec confirmation) ou |cffffd100/pano reset|r : remet chaque réglage modifié dans Panorama et chaque filtre à sa valeur par défaut. |cffffd100Annuler|r l'annule jusqu'à |cffffd100/reload|r. L'onglet Ambiance et les zones réglées sont remis à zéro aussi. Vos filtres de l'onglet Mes filtres sont effacés aussi.", "-" },
}
